{
  "batch_name": "shard-04 Flow07 协商取消页隐私号拨打-物料升版链路回归",
  "device": {
    "type": "sandbox",
    "platform": "android",
    "app": "meituan",
    "auto_install": false
  },
  "env": {
    "type": "A",
    "auth_method": "password",
    "account": "18510177674",
    "password": "ZXCasd@MT01()",
    "ptest": false,
    "bundle_lock": []
  },
  "cases": [
    {
      "case_id": "Flow07-协商取消页隐私号拨打-物料升版链路回归",
      "case_name": "Flow07-协商取消页隐私号拨打-物料升版链路回归",
      "landing_scheme": "imeituan://www.meituan.com/mrn?mrn_biz=hotel&mrn_entry=hotelchannel-order-detail&mrn_component=hotelchannel-order-detail&order_id=5035036077836749951&biz_type=1",
      "params": {
        "order_id": "5035036077836749951",
        "negotiation_order_id": "5035036077836749951"
      },
      "mock_ids": [
        "19538157",
        "19538201"
      ],
      "steps": [
        {
          "sid": "S1",
          "kind": "ui",
          "desc": "开：订单详情页点击「取消订单」进入协商取消页",
          "action": "tap-text",
          "action_arg": "取消订单",
          "step-type": "interaction",
          "page_ready": true,
          "inferred": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "进入取消流程页面（协商取消页可达：出现取消原因/取消费用等协商取消内容），而非停留在订单详情页"
            }
          ]
        },
        {
          "sid": "S2a",
          "kind": "ui",
          "desc": "L1：点击「联系酒店」唤起底部浮层",
          "action": "tap-text",
          "action_arg": "联系酒店",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "出现底部浮层，含「在线联系」与「电话联系」两个联系方式行"
            }
          ]
        },
        {
          "sid": "S2b",
          "kind": "ui",
          "desc": "L2：点击浮层「电话联系」行唤起号码选择弹窗",
          "action": "tap-text",
          "action_arg": "电话联系",
          "step-type": "interaction",
          "page_ready": true,
          "inferred": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "出现居中号码选择弹窗，列出可选电话号码与「取消」"
            }
          ]
        },
        {
          "sid": "S2c",
          "kind": "ui",
          "desc": "L3：点击号码弹窗中的具体号码唤起隐私号呼出弹窗",
          "action": "tap-text",
          "action_arg": "010-53913316",
          "step-type": "interaction",
          "page_ready": true,
          "inferred": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "出现隐私号呼出弹窗（含加密呼出说明、「取消」与「立即呼叫」）"
            }
          ]
        },
        {
          "sid": "S2d",
          "kind": "ui",
          "desc": "看：断言隐私号呼出弹窗文案（含新增双卡引导）",
          "action": "assert-text",
          "step-type": "assert",
          "asserts": [
            {
              "kind": "visual",
              "expect": "弹窗内出现「双卡双待请确认，系统呼出号码和下方一致」"
            },
            {
              "kind": "visual",
              "expect": "弹窗内出现「将使用该号码加密呼出」、掩码号码、以及「取消」「立即呼叫」按钮"
            }
          ]
        },
        {
          "sid": "A1",
          "kind": "api",
          "desc": "接口验证 queryuserinfo",
          "api_assert": {
            "path": "/hotelorder/v1/queryuserinfo.json",
            "expected_fields": [
              {
                "source": "meta",
                "field": "http_code",
                "expected": "200"
              },
              {
                "source": "response",
                "field": "error.code",
                "expected": "200"
              },
              {
                "source": "response",
                "field": "maskMobile",
                "expected": "返回非空掩码号码"
              }
            ]
          }
        },
        {
          "sid": "S3",
          "kind": "ui",
          "desc": "点击「立即呼叫」验证拨打链路",
          "action": "tap-text",
          "action_arg": "立即呼叫",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "隐私号呼叫正常发起：跳转系统拨号界面或出现呼叫发起提示（不实际接通）"
            }
          ]
        },
        {
          "sid": "A2",
          "kind": "api",
          "desc": "接口验证 bindvirtualnumber",
          "api_assert": {
            "path": "/hotelorder/v1/bindvirtualnumber.json",
            "expected_fields": [
              {
                "source": "meta",
                "field": "http_code",
                "expected": "200"
              },
              {
                "source": "response",
                "field": "error.code",
                "expected": "200"
              }
            ]
          }
        },
        {
          "sid": "S3b",
          "kind": "ui",
          "desc": "关：从拨号界面返回美团，回到协商取消页",
          "action": "back",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "回到美团协商取消页/订单页，隐私号呼出弹窗已不在前台"
            }
          ]
        },
        {
          "sid": "S4a",
          "kind": "ui",
          "desc": "再次 L1：点击「联系酒店」唤起底部浮层",
          "action": "tap-text",
          "action_arg": "联系酒店",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "再次出现底部浮层，含「电话联系」行"
            }
          ]
        },
        {
          "sid": "S4b",
          "kind": "ui",
          "desc": "再次 L2：点击「电话联系」唤起号码选择弹窗",
          "action": "tap-text",
          "action_arg": "电话联系",
          "step-type": "interaction",
          "page_ready": true,
          "inferred": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "再次出现居中号码选择弹窗，列出可选电话号码与「取消」"
            }
          ]
        },
        {
          "sid": "S4c",
          "kind": "ui",
          "desc": "再次 L3：点击号码唤起隐私号呼出弹窗",
          "action": "tap-text",
          "action_arg": "010-53913316",
          "step-type": "interaction",
          "page_ready": true,
          "inferred": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "再次出现隐私号呼出弹窗"
            }
          ]
        },
        {
          "sid": "S4d",
          "kind": "ui",
          "desc": "看：断言弹窗渲染就绪标志",
          "action": "assert-text",
          "step-type": "assert",
          "asserts": [
            {
              "kind": "visual",
              "expect": "弹窗内渲染出「将使用该号码加密呼出」"
            }
          ]
        },
        {
          "sid": "S5",
          "kind": "ui",
          "desc": "点击「取消」关闭隐私号呼出弹窗",
          "action": "tap-text",
          "action_arg": "取消",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "隐私号呼出弹窗已关闭，「将使用该号码加密呼出」不再展示"
            }
          ]
        },
        {
          "sid": "S5b",
          "kind": "ui",
          "desc": "看：关闭后无升版回归异常",
          "action": "assert-text",
          "step-type": "assert",
          "asserts": [
            {
              "kind": "visual",
              "expect": "关闭后页面回到协商取消页正常形态，无报错弹窗、无白屏、无布局错乱"
            }
          ]
        }
      ],
      "flow_source": "/Users/crazcdll07/.skills-manager/skills/ai-ui-autotest-engine/.run/tasks/c889f014/inputs/flows/Flow07-协商取消页隐私号拨打-物料升版链路回归.md"
    }
  ]
}
